INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('67a486ef-f797-4be4-9317-98225471dbfd',367586,'A Taste of Africa - Kenyan Chicken Curry','< 4 Hours','I made this recently and we loved it.  A rich, fragrant, but not overly ''burny'' curry.   Because we are not great meat eaters, I used half the chicken, the full amount of sauce, and I added a few sauteed shrimps right at the end. If you don''t have garam masala, try a curry powder that you like, I do keep roasted garam masala in my pantry.   I also let the curry sauce cook for longer than the recipe states, you should never rush a curry if you have the time!
