INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('7090f46c-7d2a-4f15-a7c2-4e45b71997d6',455335,'Kenyan Greens Simmered With Tomatoes (Sukuma Wiki)','Vegetable','Posted for ZWT7-Africa.Sukuma wiki, Swahili for "stretch-the-week," is a ubiquitous Kenyan dish. Nutritious and tasty, it is a way of "stretching" out kitchen resources. found on the internet.','PT35M','PT10M','PT45M',NULL,'1 pot','["Heat the oil over med-high flame in a large, heavy-bottomed pot. Add the onion and saute until translucent. Add the greens in batches, sauteing each addition until wilted.", "Add the tomatoes, water or stock, salt and pepper. Bring to a boil, then reduce heat to low and simmer gently until tender, from 20 to 30 minutes or done to your liking.", "Adjust seasoning and serve with a little bit of the broth.", "You can add a chopped chili pepper or two with the onions. If you like, add some leftover meat for more flavor."]','["African", "Low Protein", "Low Cholesterol", "< 60 Mins"]',231.1,8.6,12.0,28.8,6.1,3.5,NULL,105.2,1.6,2.5,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
