INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('c6eec8fe-50cb-4ef7-9443-421daf882357',510193,'Coconut Rice Pancakes (Vibibi)','Breakfast','They are also called Vibibi in Swahili and very popular amongst the East African countries, mainly Kenya and Tanzania. The trick is in the consistency, it should not be too thick nor too thin.','PT30M','PT2H','PT2H30M',NULL,'8 pancakes','["Begin by dissolving the yeast in 1/2 cup of warm water. Add a pinch of sugar and set aside, until the yeast mixture foams.", "Blend the rice flour and the Coconut milk first.", "Then add the yeast and Cardamom and blend again.", "Now, cover in a warm place to let it rise for a few hours.", "When the batter has doubled in size, add the sugar and mix well. Leave it again for about an hour or two in a warm place to rise.", "Heat up your small frying pan and add a drop oil. Spread it around the pan.", "When hot, pour some of the batter into the pan and spread to form a circle, just like the way you would when making pancakes and cover.", "Keep checking it and when golden brown on the bottom, flip it carefully.", "Repeat the process, adding more oil when necessary.", "Enjoy with a Cup of Chai (Tea)."]','["African", "Low Protein", "< 4 Hours", "From Scratch"]',2019.0,14.4,66.2,347.4,5.9,214.3,NULL,85.8,38.5,NULL,0,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
