INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('15ffe313-30f9-41f2-a286-059b89df6f8d',456927,'Kenyan Tomato Salad - Quick & Simple Side','Vegetable','A very simple side salad which would go nicely alongside a curry and rice.  There isn''t much to this, the beauty is in its simplicity.  According to the Int''l Vegetarian Union, this is a Swahili recipe, common in Kenya & Tanzania. (www.ivu.org)',NULL,'PT15M','PT15M',NULL,'4 as a side','["Arrange sliced tomatoes and onions on a salad plate.", "Mix together garlic, lime juice, salt, and pepper.", "Pour dressing over tomatoes and onion."]','["African", "Low Protein", "Vegan", "Low Cholesterol", "Healthy", "Summer", "< 15 Mins", "Easy"]',38.5,1.6,0.3,8.7,2.1,4.9,NULL,8.2,0.1,5.0,9,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
