INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('4bad70ae-3c64-4abc-8d85-7fde85de803c',308971,'Barbecued Chicken -(Kuku Wa Kuchoma)','Curries','This grilling recipe came from a KENYA AND TANZANIA web site and is specifically a Swahili recipe.  Serve hot with salad and rice or potatoes.  Posted for ZWT4.','PT15M','PT30M','PT45M',4,NULL,'["Fire up your grill.", "Place all ingredients except chicken in blender or food processor and blend until finely chopped.", "Spread the resulting mixture over the chicken and let it stand for 20 to 30 minutes (or even longer).", "Barbecue the chicken over a charcoal fire, medium heat, until it is cooked about 15-20 minutes."]','["Chicken", "Poultry", "Meat", "African", "Very Low Carbs", "High Protein", "High In...", "< 60 Mins"]',738.2,57.7,53.0,4.3,0.6,1.2,243.8,228.5,15.1,4.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
