INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('a360671f-de7d-4b60-a7c3-f97efa61d09c',455496,'Dawa','Beverages','This comes from the book Around the World in 80 Bars, and the recipe comes from "The Carnivore" in Nairobi, Kenya.  The Carnivore is a nyama choma (barbecued meat) restaurant, and is licensed to serve gazelle, giraffe, and zebra.  In Swahali, Dawa means "somewhere between a medicine and a magic potion''.  Traditionally, this drink is served with a small wooden masher so that you can release more lime juice and adjust the flavor of your Dawa to suit your liking. This is a pretty strong tasting drink, so I generally release more lime juice!!',NULL,'PT10M','PT10M',1,NULL,'["Place the lime slices, honey and sugar in a heavy-based rocks glass and crush lightly together with a spoon.", "Add some ice, and pour the vodka over it.", "Adjust the flavor by crushing the lime slices further, if desired."]','["Lime", "Citrus", "Fruit", "Low Protein", "Low Cholesterol", "Healthy", "< 15 Mins", "No Cook", "Easy"]',238.9,0.5,0.1,28.6,1.9,22.6,NULL,2.8,NULL,5.0,9,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
