INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('329d582e-7aeb-4af8-aa3f-dda3e2909708',173116,'Dawa (African Cocktail)','Beverages','Dawa means "medicine" or "magic potion" in Swahili. In other words, a dawa is said to be so potent that it will cure whatever ails you. The recipe is based on a famous Brazilian drink that was introduced to Kenya. It is now one of the most widely consumed cocktails in Kenya and has spread through out North and South Africa (especially in touristy regions). Recipe compiled through different sources while researching African Beverages. Enjoy!',NULL,'PT5M','PT5M',1,NULL,'["Put lime and sugar into a whisky tumbler.", "Crush limes slightly, add ice and pour in the vodka.", "At this point you twist a dawa stick into some honey and add the stick to the drink. A wooden honey stick or other type of stick twisted in honey will work.", "Muddle limes with dawa or honey stick. The more you crush the limes into the mixture and stir the sweeter the taste."]','["Lime", "Citrus", "Fruit", "African", "Low Protein", "Low Cholesterol", "Healthy", "< 15 Mins"]',164.8,0.5,0.1,11.3,1.9,5.3,NULL,1.9,NULL,5.0,5,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
