INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('1a0e0c47-0c9b-43b3-91f5-bf37ab38b6f1',164728,'Kenyan Ground Round Curry','Curries','This goes really well with spaghetti. It also works really well with 12 ounces of meatless "meat" instead of beef. In Kenya this is called Kima Curry.','PT20M','PT10M','PT30M',NULL,NULL,'["In a deep medium-sized frying pan, saute onions and ground beef in oil until meat is browned. Skim fat.", "Add curry powder, garlic, ginger and tomatoes. Fry briefly, then add tomato paste, cinnamon and cilantro.", "Stir and add water and salt to taste.", "Simmer 20 minutes over medium heat to blend flavors. Serve over rice, spaghetti or with chapatis."]','["Meat", "African", "Kid Friendly", "Spicy", "< 30 Mins"]',305.7,24.5,18.5,10.3,2.5,4.7,73.7,115.0,5.5,5.0,7,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
