INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('fee1f987-df6c-40e1-96ff-4a206d9954a8',308897,'Rice Cooked in Coconut-(Wali Wa Nazi)','Rice','This recipe is from a KENYA AND TANZANIA site and is specifically a    Swahili recipe.  It is a starchy staple and they "serve it with curry or main dish". I have added a 3/4 cup of liquid since looking at Weekend''s reviews. Posted for ZWT4.','PT30M','PT5M','PT35M',4,NULL,'["Clean and wash rice.", "Bring the coconut milk and water to a boil.", "When boiling, pour in the rice.", "Add salt.", "Leave to cook on medium heat.", "When nearly dry, cover well.", "Turn down the heat and leave to cook for 10 minutes.", "(If you have a rice cooker, put all of the ingredients in the rice cooker and turn it on.).", "Watch it to make sure it does not burn, adding more water if needed to keep it from burning."]','["African", "Low Protein", "Healthy", "< 60 Mins", "Beginner Cook", "Stove Top", "Easy", "Inexpensive"]',879.4,8.2,24.7,156.1,1.7,76.2,NULL,640.5,23.1,4.0,4,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
