INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('2de833e4-e5a6-42cc-b6d5-1dc062dac9dd',308910,'Fried Cauliflower --(Bilingani La Kukaanga)','Cauliflower','This recipe came from a KENYA AND TANZANIA web site and is specifically a Swahili recipe.  Posted for ZWT4.','PT15M','PT5M','PT20M',6,NULL,'["Put oil into a frying pan.", "Fry onions.", "When onions are brown, add all the ingredients except water.", "Fry for 2 to 3 minutes.", "Add water.", "Cover and cook till tender and all the stock is dry.", "Serve hot as a vegetable dish."]','["Onions", "Vegetable", "African", "Low Protein", "Vegan", "Low Cholesterol", "Healthy", "< 30 Mins", "Stove Top", "Inexpensive"]',122.0,2.6,9.4,9.0,3.4,4.5,NULL,32.8,1.2,5.0,6,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
