INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('25e07cbf-74f2-4f26-8cc8-c0c858beef02',432377,'Tamu Sana Kuku Paka','Curries','Tamu sana means "very delicious" in Swahili, the language spoken in Kenya, where I grew up.  Kuku Paka is a hybrid dish coming from Swahili, Arab, and Indian influences.  It is my husband''s favorite dish, and my kids love to say the name of it when they ask me to make it.  Kuku means chicken in Swahili, but nobody that I have asked knows what the Paka part is supposed to mean.  It is a mild, creamy, and comforting dish.','PT45M','PT1H','PT1H45M',NULL,NULL,'["Place the chicken thighs in a plastic freezer bag with half of the ginger (1 1/2 tbsp), half of the garlic (1 1/2 tbsp), half of the vegetable oil (2 tbsp) and a third of the kosher salt (1 tbsp).  Leave to marinate in the fridge for at least one hour or even overnight.", "Preheat the oven to 375 degrees Farenheit.", "Cover two cookie sheets with foil and spray each with a nonstick cooking spray.", "On one sheet, place the chicken thighs, skin side up, in a single layer.", "Peel the potatoes and cut them into quarters.  Put them in a single layer on the second cookie sheet.  Spray the potatoes and sprinkle with a third of the kosher salt (1 tbsp).", "Roast the potatoes and chicken in the oven for 45 minutes.", "While the chicken and potatoes are cooking, make the gravy: Finely dice the onion and fry it in the other half of the vegetable oil (2 tbsp) until the pieces turn a light brown color.  Add the spices, the rest of the garlic and ginger ( 1 1/2 tbsp each), the rest of the salt (1 tbsp), the sugar, the serrano chili, and the tomatoes.  If you like it spicy, pound on the chili with a mallet or cut it up into small pieces.  If you like it mild, cut two slits into the chili, but do not split it open.", "Cook, constantly stirring, for about five minutes, or until the tomatoes start sticking to the bottom of the pot.", "Pour in the coconut milk and stir to combine.  Heat until hot but not boiling.  Add the lime juice, eggs, and some cilantro (leave some for garnish).  Taste for seasoning and add more salt, sugar, or lime juice to taste.", "When the chicken and potatoes are ready, place the potatoes directly in the gravy -- they should be slightly browned on the edges.  Take the skin off the chicken and put the chicken in the gravy as well (leave the meat on the bone, or take it off if you''d like).  Be sure not to boil the gravy or the coconut milk will curdle.", "Garnish with cilantro and slices of limes.", "Serve with fresh basmati rice or thick slices of a crusty soft French bread for dunking."]','["Chicken Thigh & Leg", "Chicken", "Poultry", "Meat", "African", "< 4 Hours"]',1382.0,40.8,92.7,109.5,18.5,30.4,290.5,5794.6,59.9,5.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
