INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('f0446bb6-3d30-4c02-9805-8e7e221b0b00',456503,'Kuku Paka (Kenyan Chicken Curry)','Chicken','Make and share this Kuku Paka (Kenyan Chicken Curry) recipe from Food.com.','PT1H','PT15M','PT1H15M',NULL,NULL,'["Add the onion, chiles, ginger and garlic to a food processor or blender and process until smooth. Add a little water if necessary.", "Heat the oil or ghee in a large pot or wok over medium flame. Add the onion puree, curry powder and cumin and saut\u00e9, stirring frequently, for 5 to 8 minutes, or until cooked down.     Stir in the tomatoes and simmer for 3 to 4 minutes. Then add the chicken, coconut milk, salt and pepper. Reduce heat to low and simmer, covered, until the chicken is cooked through and tender, anywhere from 30 minutes to an hour. Add more water as needed.  Adjust salt and pepper, to taste.", "Stir in the cilantro.  Serve with with rice or chapatti.", "Variations:  For authentic flavor, grill the chicken pieces before stirring them into the simmering sauce. If you like, you can also use boneless, skinless chicken breasts or thighs.", "Some recipes add potatoes or hard-boiled eggs to the curry. The potatoes can be cooked ahead, cut into chunks and stirred into the curry toward the end.", "Eliminate the hot chiles for a milder dish. Or substitute a chopped sweet bell pepper.", "Reserve some of the coconut cream that gathers at the top of the can and stir it into the sauce at the very end for extra silky results."]','["Poultry", "Meat", "African", "< 4 Hours"]',1434.6,67.3,89.8,90.3,3.0,81.1,255.2,303.2,39.4,4.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
