INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('33f9863f-0eef-4730-b9b3-27d3ea246242',456632,'M''bazzi (Pea Beans Nairobi Style)','Beans','Pea beans paired with peppers & coconut milk served in lettuce leaves is often served as a welcome back to camp appetizer after a long day in the brush. This recipe comes from kenya-advisor.com. Navy beans or black eyed peas can be substituted for pea beans. Posted for ZWT7; Africa. Note: food.com wouldn''t let me list as pea beans, so I entered as navy beans.','PT1H','PT15M','PT1H15M',6,NULL,'["Cook beans in salted water for about an hour, or until tender, drain, set aside.", "In a sauce pan heat oil; add bell pepper, onion, cayenne and salt; saute until onion is tender; add beans; cook about 2 min.; stir in coconut milk; cook until sauce is about the consistency of a medium sauce and sticks to the beans.", "Refrigerate mixture until it is throughly cold, best if you can leave in the refrigerator at least 24 hours to allow the spices to meld with the beans.", "Place individual lettuce leaves on a large platter, place a 1/2 cup serving of bean/coconut mixture on each lettuce leaf, top with tomatoes and parsley; serve as a salad or appetizer."]','["Vegetable", "African", "Low Protein", "< 4 Hours"]',316.8,4.0,17.5,38.0,4.5,27.2,NULL,493.8,8.9,NULL,0,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
