INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('06cc68cf-2fc8-4d86-b4f0-4e5c16139f56',229821,'Ground Beef Curry (Kima Curry)','Curries','This recipe is from one of my new favorite cookbooks, Extending the Table.  The notes on this recipe say that this Swahili dish is served by a restaurant in the heart of Nairobi.  I have only modified it to make the recipe fit into Zaar format, to preserve the authenticity of the recipe.  This is a very mild, very easy to make curry.','PT20M','PT10M','PT30M',NULL,NULL,'["In a skillet, heat oil over medium high heat.  Saute onion and beef until browned.  Drain fat.", "Add in curry powder, garlic, ginger, and tomatoes and fry briefly.", "Stir in the rest of the ingredients.  Turn down heat to medium and cook for 20 minutes to blend the flavors.", "Serve over rice or with Chapatis."]','["Meat", "African", "< 30 Mins", "Easy", "Inexpensive"]',305.8,24.5,18.5,10.3,2.5,4.7,73.7,115.0,5.5,4.5,31,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
