INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('8888fe60-a360-4a8e-b66b-bec19a00f626',455974,'East African Cardamom Tea','Beverages','I just tried this tea and it was lovely with Earl Grey. Not liking the idea of ground cardamom in tea I switched the recipe to using the full pods and steeped them with my tea leaves. Originally posted for ZWT7, Africa. Modified from, www.congocookbook.com.','PT3M','PT5M','PT8M',NULL,'1 pot','["In a saucepan or tea kettle heat the water to a near boil. Transfer the water to a teapot and add the tea leaves, and bruised cardamom pods, steep tea as normal.", "Pour the tea into cups with sugar or honey, and milk to taste.", "Stir, serve and enjoy!"]','["African", "Free Of...", "Sweet", "Weeknight", "< 15 Mins", "Easy"]',0.1,NULL,NULL,NULL,NULL,NULL,NULL,0.1,NULL,5.0,13,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
