INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('bf89b2f2-1689-48e1-91da-7acb7b62d0f7',140780,'Mbaazi Wa Nazi (Pigeon Peas in Coconut Milk)','Coconut','Mbaazi wa Nazi (Pigeon Peas with Coconut) are the Swahili way to prepare this popular tropical pulse. The pigeon pea is evidently native to Africa or Asia. In Egypt, the cultivation of pigeon peas began before 2000 B.C. Today pigeon peas are widely cultivated in all tropical and semi-tropical regions the world over, and are especially popular in India and the Caribbean.','PT1H','PT5M','PT1H5M',NULL,NULL,'["In a large pot, combine pigeon peas and just enough water to cover. Bring to a boil, reduce heat, cover, and simmer until the peas begin to become tender and most of the water is absorbed.", "Stir in 1 1/2c coconut milk.  Continue to simmer over low heat. Add more water as necessary to prevent the peas from becoming dry.", "While peas are simmering: Heat a few tablespoons of oil in a skillet. Add the curry powder to the oil and stir for a minute. Fry the onion and chile pepper until they are tender.", "Combine the peas and onion-chile mixture (add either one to the other). Continue to simmer until peas are tender enough to eat. Add the remaining coconut milk and simmer on the lowest possible heat for five to ten minutes, stirring occasionally.", "Serve \\", " with Chapati (Basic Chapati Recipe #137408), rice, or \\", " with Ugali."]','["Beans", "Fruit", "Nuts", "African", "Vegan", "Healthy", "< 4 Hours", "Easy"]',931.3,26.8,25.9,153.1,18.1,77.5,NULL,74.0,23.3,5.0,8,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
