INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('d30770a1-f57f-4732-91cf-40f1ca310257',443694,'Lentils With Onions and Tomatoes','Lentil','This is a wonderful, easy to prepare lentil dish that I received from a friend.  She had attended a potluck where she sampled this Kenyan dish that her co-worker prepared from her home country.  Delicious!','PT35M','PT10M','PT45M',4,NULL,'["Put lentils, bouillon cube, and water into a pot and bring to a boil.  Reduce heat to medium and allow to simmer until lentils are soft and most of the water is absorbed, about 20-25 minutes.", "Meanwhile, in a separate saute pan, add oil and onions and saute until onions are soft and browned.", "Stir in tomatoes, garlic powder, and rosemary.  Let cook over medium heat until tomatoes are cooked down a bit, about 2-3 minutes, stirring occasionally.", "Combine lentils and onion mixture, stirring well.", "Adjust temperature to low.  Pour in whipping cream, stirring gently.", "Allow to heat through on low for an additional 5-10 minutes, stirring occasionally."]','["Beans", "Low Protein", "Low Cholesterol", "< 60 Mins"]',166.3,5.9,9.4,16.2,5.2,3.9,20.5,253.7,4.0,5.0,6,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
