INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('c7c7458a-7ada-406a-9819-4dff1e27b8f0',248887,'Hakuna Matata All-African Barbecue Sauce!','Sauces','This is equally good for red meats and poultry. The quantities given are flexible, but I suggest staying more or less with these ingredients and tasting! Yes, we like our spices, and yes, it''s spicy, tangy and tasty!! Pour into a glass jar with a screwtop -- lasts forever in the fridge! Don''t salt your meat before grilling; there is salt in this sauce. Baste meat with a brush as you grill it and when you turn it over. Can be used as a marinade for red meats like steaks. "Hakuna Matata" means "No Problem!" in Swahili ...',NULL,'PT10M','PT10M',NULL,'4 cups','["Put all ingredients in a processor.", "Process until thickish and smooth.", "Taste for seasoning. If too sweet to your taste, add a little more vinegar.", "(Our South African chutneys are not very sweet, neither are our ketchup and mustard sweet -- your products I am not familiar with. So if you use too-sweet products the sauce will also be too sweet).", "This basting sauce must stand before use so the flavours can meld -- at least 30 minutes.", "Keep in a screwtop bottle in the fridge, and shake or stir before use if it separates.", "Can be used as a marinade, but we prefer to use it for basting. You can also chuck in a few onion chunks when processing."]','["South African", "African", "Kid Friendly", "< 15 Mins", "Easy"]',702.0,1.6,55.5,52.0,1.8,46.8,NULL,2097.8,7.2,5.0,5,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
