INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('ed2e266e-c109-4597-9a3d-cf2d7f92dfbe',309861,'Spicy Matoke (Plantains)','African','Plantains are a staple in most of Africa. This Kenyan recipe also shows a south Asian influence. From "The Africa Cookbook".','PT40M','PT5M','PT45M',NULL,NULL,'["Peel the plantains and slice in 1-inch pieces.", "Place them in a bowl with the lemon juice and enough lukewarm water to cover.", "In a large skillet, heat the ghee.", "Fry onions, cilantro, and chile until onion is translucent.", "Drain the plantain pieces. Add to the skillet with the stock.", "Simmer, uncovered, about 30 minutes, until the plantains are done."]','["< 60 Mins"]',326.5,3.5,3.0,80.3,6.0,37.5,5.5,10.8,1.7,4.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
