INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('2e26cf63-1f9c-4ee3-90a0-8c78c3769c19',417344,'Cherry Tomatoes With Tamarind Dressing','Salad Dressings','ZWT7 Africa. Tomato is a very popular staple and foodstuff in Africa. The tamarind is used in cooking as well. In southern Kenya, the Swahili people use it to garnish legumes and also make juices. In Madagascar, its fruits and leaves are a well-known favorite of the ring-tailed lemurs, providing as much as 50% of their food resources during the year if available. In northern Nigeria, it is used with millet powder to prepare kunun tsamiya a traditional breakfast item. Here pared with tomatoes and a little spice this would work wonderfully with other African dishes. Recipe from Contributor, Elinoar Moore on www.inmamaskitchen.com.','PT4M','PT10M','PT14M',6,'6','["Toast cumin and fennel seeds then coarsely crush using a mortar and pestle.", "Whisk tamarind concentrate into hot water until dissolved, then whisk in honey (to taste), oil, salt, and pepper until blended. Add tomatoes and toasted seeds and toss to coat. Let stand at room temperature 1 hour, then season with salt to taste. (We found if it sat many more hours in the fridge it was not to our tastes at all because the fennel flavour became stronger.)."]','["Southwest Asia (middle East)", "Asian", "Lactose Free", "Low Protein", "Low Cholesterol", "Egg Free", "Free Of...", "Weeknight", "< 15 Mins", "Easy"]',40.3,0.8,2.5,4.6,1.1,3.4,NULL,101.5,0.3,5.0,5,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
