INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('6f163f91-5273-4739-944a-68c4f782b915',454997,'Mchicha (East African Spinach','Spinach','Make and share this Mchicha (East African Spinach recipe from Food.com.','PT15M','PT15M','PT30M',NULL,NULL,'["Place spinach and salt in a heavy 4-5 quart casserole.", "Cover tightly and cook over medium heat until spinach is tender, about 10 minutes.", "Drain spinach, squeezing it completely dry a handful at a time.", "Chop coarsely and set aside.", "Melt butter in a large, heavy skillet over moderate heat.", "Add onions and chilies and cook, stirring frequently, until soft but not brown, about 5 minutes.", "Stir in coconut milk and peanuts and bring to a simmer over moderate heat.", "Reduce heat to its lowest point.", "Cook uncovered, stirring frequently, 2-3 minutes.", "Add spinach and cook until heated through, 4-5 minutes more."]','["Greens", "Vegetable", "Nuts", "African", "Low Protein", "< 30 Mins", "From Scratch"]',485.3,10.8,27.6,55.8,7.4,40.8,15.3,841.9,16.4,5.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
