INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('db3b1b48-e63f-458a-928f-2c80d51d5360',304816,'Maharagwe (Red Beans)','Beans','The Swahili people have two ways to cook beans:  sweet or savory.  Skip the optional ingredients to make Sweet Beans, which are eaten at the end of lunch or dinner.  For special dinners add all the optional ingredients to make Savory Beans.  Savory beans are also eaten with bread for breakfast.  From "The Congo Cookbook".  Posted for ZWT #4.','PT1H','PT20M','PT1H20M',NULL,NULL,'["Rinse and drain soaked beans.  Place beans in a large cooking pot and add fresh water to cover.", "Bring to a fast boil and cook for 10 minutes.  Reduce hat and simmer until beans are nearly tender.", "Add all remaining ingredients.  Cover and cook until all is tender, stirring occasionally."]','["African", "Healthy", "< 4 Hours", "Easy"]',599.0,21.6,13.1,102.2,14.2,46.3,NULL,619.1,11.6,4.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
