INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('ba7eee66-35e1-49b2-85b0-a29177b9709b',307565,'Irio (Kenya)','Potato','Native to Kenya, this mash combines potatoes with watercress, peas and corn.  Easy to prepare and delicious.','PT15M','PT15M','PT30M',6,NULL,'["Peel potatoes and slice into thick wedges. Place in large pot of water and bring to a boil.  Cook until the potatoes are tender but not falling into a mush.", "Pour off the water and begin to mash the potatoes by hand.  Add in the watercress, peas and corn and mix everything until well combined.", "Season the mash with butter, salt and pepper to taste.", "Serve hot."]','["Corn", "Vegetable", "African", "< 30 Mins", "Stove Top", "Easy"]',187.2,4.9,2.5,38.4,5.0,3.6,5.1,345.6,1.3,5.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
