INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('a292cd06-11f0-4089-8043-cda9b0b65332',310167,'Safari Steak for the Hunter','Steak','This recipe is from Kenya.  It is used by hunters on safari in preparing zebra, eland, antelope, or other game.  The technique is good and can be used on our favorite food-beef steak.','PT40M','PT10M','PT50M',8,NULL,'["Heat oil and butter in a 10 to 12 inch skillet until almost smoking.", "Fry steaks in pan, a few at a time, for about 3 minutes on each side, adding more oil and butter as needed.", "Season each steak with salt and pepper and set aside, keeping warm.", "Lower heat and add red wine and dessert wine.", "Stir with residue left in pan.", "Add garlic and cook for 2 minutes.", "Add tomato paste and water.", "Cook until sauce is quite thick.", "Combine mashed potatoes and yams(or sweet potatoes) ina 2 qt saucepan and beat thoroughly.", "Season the potato mixture to taste.", "Spread the potato mixture on a large platter.", "Arrange the steaks on the potatoes.", "Pour the sauce over the steaks.", "Sprinkle with chopped parsley."]','["Meat", "African", "< 60 Mins"]',815.3,43.5,52.6,26.9,3.1,4.1,169.5,235.3,21.3,4.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
