INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('9c85269a-2206-4160-ae27-e9a94bf136ed',310341,'Mchicha - Tanzanian Spinach & Peanut Curry.','Curries','Mchicha is a very traditional dish in Tanzania & can be made like this with peanut butter - homemade or natural is best - or it can be made with a whole coconut (grated flesh & milk) instead. Posted for ZWT 4.','PT35M','PT10M','PT45M',NULL,NULL,'["Wash the spinach & roughly chop. De-skin the tomato,  peel and chop. Peel and chop the onion.", "Mix the peanut butter with the coconut milk in a jug & set aside.", "Heat the ghee . butter  over a medium heat in a large frying pan. Add the onion, tomato, salt and curry powder / paste and saut\u00e9 for 5 minutes, or until the onion becomes soft.", "Add the spinach, continue cooking for about 15 to 20 minutes, until the spinach is cooked.", "Pour  the peanut butter and coconut milk mixture into the pan & stir gently to mix.", "Simmer, for another 5 minutes, stirring constantly, to ensure that the mixture does not stick to the pot.", "This dish makes a lovely side dish, & can also be eaten with rice, ugali or samp and beans to form a delicious  main course."]','["Spinach", "Greens", "Onions", "Fruit", "Vegetable", "Nuts", "African", "Free Of...", "Spicy", "< 60 Mins", "Stove Top", "Easy", "Inexpensive"]',361.3,11.8,29.1,21.1,8.3,8.5,24.6,849.7,18.9,5.0,10,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
