INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('edb1cc9f-f21e-485b-87e4-67d788132422',356829,'Chapatis (Indian or Kenyan Wholewheat Flatbread)','Breads','This is a recipe by Guy Fieri that I saw on Guy''s Big Bite. Easy and tasty - a really good recipe. The cooking time is for only one batch of griddling because it depends on how big your griddle is. Each flatbread counts as 1 WW point. Enjoy!','PT5M','PT35M','PT40M',8,'8 flatbreads','["In a medium bowl, combine flour and salt. Using a wooden spoon, slowly stir in water, until dough forms. Lightly flour a clean board and knead dough until smooth, about 10 minutes. Rest dough in bowl, covered with damp towel for 20 minutes.", "Preheat a griddle over medium heat.", "Divide dough into 8 equal balls. Using a floured rolling pin, roll balls out on floured board to 7 inches in diameter, about 1/4-inch thick. Place the rolled out dough onto griddle. Flip when raised bumps appear on the surface of the dough, about 1 to 2 minutes. Cook second side until it turns golden. Do not cook too long or flatbread will become brittle. Cover flatbread with a towel up to 20 minutes before serving."]','["Greek", "European", "Low Cholesterol", "Healthy", "Brunch", "< 60 Mins", "Beginner Cook", "Easy", "Inexpensive"]',76.5,3.0,0.6,16.2,2.4,0.1,NULL,292.0,0.1,5.0,4,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
