INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('39c6a573-fb20-4b32-8a98-f52369e8baa4',455152,'Fish in Coconut Milk Curry','African','This is an original Swahili recipe from Kenya. Posted for ZWT7-Africa. I found this on the internet.','PT25M','PT15M','PT40M',NULL,'1 pot','["Cut the fish in serving pieces.", "Chop the onion, bell pepper, garlic, and tomatoes in small pieces.", "Heat the oil over medium-high heat in a large pot.", "Sear the fish filets and put them on a separate plate. Do not cook through.", "Reduce the heat to minimum and add the pepper and onion. Saute until the onion is semi-transparent.", "Add the garlic, and saute for 2 minutes.", "Add the tomatoes and bring to a boil. Add the rest of the ingredients, bring to a boil and reduce heat to simmer.", "Add salt and pepper to taste. Add the fish filets.", "Cover the pot and simmer until the fish is cooked through, which should take up to 10 minutes.", "Serve with rice, boiled potatoes, chapatti, or broiled cassava."]','["Very Low Carbs", "< 60 Mins"]',663.4,81.1,31.5,13.8,2.4,6.5,187.0,284.6,18.0,5.0,5,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
