INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('51907f67-2185-4511-a36a-1a40ae9395d2',455752,'Maharagwe--(Spiced Red Beans in Coconut Milk)','Beans','This is a recipe fron Kenya. There are a few ways to prepare Red Beans in Africa and different areas seem to prefer different seasonings. The coconut milk in this recipe is the traditional way to make your own, but you can substitute canned to save yourself the trouble. You can also substitute canned kidney beans for the dried. Posted for ZWT, Africa.','PT1H30M','PT20M','PT1H50M',NULL,NULL,'["In a large pot, cover the beans with water and simmer until they are just tender, about an hour. Saute onions in oil until golden brown. Add the remaining ingredients to the pot and simmer several minutes until the beans are very tender and the tomatoes are cooked (about 20 minutes). Serve over rice or a stiff porridge.", "For the coconut milk:", "Makes about 3 cups.", "fresh white meat of 1 coconut", "Grate the meat by hand or process it in a blender. To extract the flavorful moisture from the gratings, it is easy to mimic the Africans'' method of using a conical woven basket. Line a bowl with a cotton cloth such as cheesecloth, making sure that the lining is big enough to drape over the sides of the bowl. Dump the grated coconut onto the cloth and then pour 1 cup of boiling water over it. When it is cool enough to handle, gather the edges of the cloth and lift it above the bowl. Wring it with both hands to squeeze out the mlky liquid, which you should pour off and save. Repeat this process three times.", "The first squeezing is the most concentrated, so you should keep each squeezing separate and use them in order (i.e., use the first squeezing as the first cup in a recipe, etc.)."]','["African", "< 4 Hours"]',763.9,14.0,28.5,118.2,9.7,83.0,NULL,648.9,23.5,5.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
