INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('3466ed2f-263a-4510-9684-40b077b95363',140774,'Chapati (East African Bread)','Breads','This is taken from the Congo Cookbook. Unleavened bread that is very popular and is served with many curry dishes. I am estimating the servings as I have not made this yet. It looks good and simple so I do plan on making.','PT30M','PT30M','PT1H',NULL,NULL,'["All ingredients should be allowed to come to room temperature if they have been in the refrigerator.", "Mix flour and salt in a bowl.", "Slowly mix in enough water to make a thick dough.", "Mix in one spoonful oil.", "Knead dough on a cool surface for a few minutes, adding a few spoonfuls of dry flour.", "Return dough to the bowl, cover with a clean cloth, and let it rest for thirty minutes.", "Lightly grease (with cooking oil) and pre-heat a skillet or griddle.", "Divide the dough into orange-sized balls. Flatten them into six-inch circles. Fry them in the skillet or griddle, turning once, until each side is golden brown and spotted.", "Place in warm oven as they are done and serve with butter and any curry, stew or soup dish."]','["African", "Low Cholesterol", "Healthy", "< 60 Mins", "Easy"]',158.3,4.3,1.2,31.8,1.1,0.1,NULL,388.4,0.2,4.5,11,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
