INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('491103de-5bec-4b50-99e8-08fc1bc3c125',142433,'Beef Pilau','Stew','Great use of beef stew meat!  Wonderful beef stew with coriander, coconut and tomatoes.  This is a dish from  East Africa, but has lots of Indian influence.  It combines the Indian spice coriander with several classic African ingredients...peanuts, coconut, tomatoes, and green beans. I think you could substitute okra for the green beans if you wanted to.','PT1H30M','PT10M','PT1H40M',6,NULL,'["Brown beef in a dutch oven, half at a time, in hot oil.  Remove and set aside, reserving drippings.  In drippings, cook onion and garlic till tender but not brown.  Return all meat to dutch oven.  Drain off fat.", "Add coconut milk, undrained tomatoes, salt and coriander into meat mixture.  Bring to boiling, reduce heat.  Cover, simmer about 1 hour.", "Stir in beans (or okra), rice and peanuts.  Simmer, covered, for 25 to 30 minutes or until liquid is absorbed and until meat and rice are tender."]','["Long Grain Rice", "Rice", "Meat", "African", "Savory", "Stove Top", "< 4 Hours", "Easy"]',836.9,33.5,39.7,90.9,4.4,54.6,72.6,524.0,20.3,5.0,6,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
