INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('3679ec0a-f828-4c94-94df-a841555311ca',369809,'Mombasa Chicken','Chicken Thigh & Leg','This is a very easy recipe that is FULL of flavor. Since each piece of chicken is cooked in it''s own aluminum foil pouch the spices can be increased or decreased to suit your individual taste, which is great for the little ones.  This is great over rice or noodles.','PT1H','PT20M','PT1H20M',NULL,NULL,'["Preheat oven to 425.", "Place each thigh on a piece of aluminum foil (large enough to fold up & over the chicken so it won''t leak).", "Dust each piece with about 1/8 teaspoon of the salt, pepper & garlic powder.  Add a pinch of curry & cyan pepper.  Top each piece of chicken with 1 teaspoon molases & 1 1/2 teaspoon soy sauce.", "Fold up the aluminum foil & place in a foil lined pan (just in case one leaks).", "Bake for 1 hour."]','["Chicken", "Poultry", "Meat", "African", "High Protein", "High In...", "< 4 Hours"]',341.7,26.1,21.7,9.7,0.6,5.9,118.4,1447.3,6.0,5.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
