INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('d28d6c30-e8e6-4f2d-a044-358866f6fa1f',456300,'Curry of Beef Zanzibar','Roast Beef','What a lovely curry dish this is! It is quite yellow in color, and the sauce is smooth and velvety. It is the combination of all the spices which makes this great dish. Use a good quality of curry and make it with any meat. It is frequently served with beef liver in East Africa. Try it with lamb or veal as a change.','PT1H15M','PT15M','PT1H30M',8,NULL,'["In a 4 quart saucepan, saute the first 7 ingredients until onions are soft.", "Add the Beef.", "Saute lightly but do not permit the meat to brown.", "Add water and lemon juice.", "Cover tightly and allow to simmer for 1 hour.", "If the sauce appears thin, thicken it with cornstarch and 2 T. water mixture.", "Serve in a 4 quart oval bowl with RICE cooked in chicken or beef broth (allow 1 cup cooked rice per portion).", "In a 6-sectioned relish dish or six small bowls, place each of the relishes.", "Place the relish dish on the tables so guests may help themselves."]','["Meat", "African", "< 4 Hours"]',283.5,24.9,17.3,8.9,1.8,3.0,74.8,389.4,7.1,4.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
