INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('ca1dae24-cc18-4031-b4d5-af881842c4c7',306835,'Tanzanian Pineapple Salad','Pineapple','Make and share this Tanzanian Pineapple Salad recipe from Food.com.','PT1H','PT15M','PT1H15M',8,NULL,'["Peel the pineapples and cut the flesh into cubes.", "In a dry frying pan, toast separately the cashews and coconut until lightly browned, then set aside to cool.", "Mix together the cream, honey and rum to taste and pour this mixture over the pineapple cubes.", "Reserve some of the toasted cashews and coconut to use a garnish, then add the remainder to the pineapple.", "Mix well and place in the refrigerator to chill.", "Before serving, garnish with the reserved cashews and coconut slivers."]','["Tropical Fruits", "Fruit", "Nuts", "African", "Summer", "< 4 Hours"]',316.8,3.8,18.2,36.9,3.7,26.0,33.2,87.5,9.9,5.0,4,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
