INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('86d38191-6786-472b-9deb-b7d4a77fb88f',309925,'King Prawns in Swahili Sauce','African','Mike Robinson''s African recipe for king prawns in an aromatic coconut milk sauce and coriander rice Easy to make','PT20M','PT20M','PT40M',4,NULL,'["Place the washed basmati in a heavy-based medium saucepan. Add the juice of 3 limes, the chopped coriander stalks, 400ml coconut milk and salt to taste. Add just enough water to make the liquid in the pan come level with the rice.", "Bring the rice to the boil and simmer for 5 minutes. Cover tightly, remove from direct heat and set aside for 15 minutes by which time the liquid will be absorbed and the rice cooked through.", "Toss the prawns with the remaining lime juice and set aside to marinate briefly.", "Heat the oil in a heavy-based saucepan. Add the lemon grass, ginger, garlic, shallot, chillies, garam masala and turmeric and fry, stirring often, until the shallot has softened.", "Add the remaining coconut milk and the plum tomatoes. Season with salt and freshly ground pepper. Simmer for 5 minutes.", "Increase the heat and add the king prawns. Cook for a further 2 minutes, turning the prawns to ensure even cooking.", "Serve the prawns with the coriander rice, garnished with the coriander leaves."]','["< 60 Mins"]',752.8,14.3,39.2,93.0,4.7,4.0,17.6,113.0,29.9,4.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
