INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('af73fe6a-dd47-435a-b74f-020cdd6f2b00',375912,'African Spinach and Groundnut Stew (Aka Peanut, Kenya/Tanzania)','< 30 Mins','This is from "Best of Regional African Cooking". The original calls for 1/2 c. finely ground unsalted peanuts.  That''s too much work, so I substituted peanut butter.  This is a very thick, rich vegetable side.  It is not a stew like we think of stews in the US.  My husband liked it, and it is the only spinach dish he will eat.','PT15M','PT10M','PT25M',6,NULL,'["Saute onions and chili pepper in oil until onion is transparent.", "Add peanut butter and coconut milk slowly, stirring constantly until it comes to a boil.  Add spinach.  Salt to taste.", "Reduce heat and simmer 15 minutes or until spinach is cooked."]','["Easy"]',171.8,7.6,13.5,8.8,3.1,3.6,NULL,134.9,2.6,NULL,0,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
