INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('16537d2e-22b6-4fce-8c3a-86ebdee18bcb',455976,'African Fruit Salad','Dessert','ZWT7, Africa. "A wide variety of tropical fruits, both native and non-native, are cultivated in Africa. In Western Africa, the closest thing to a dessert course is the "after-chop" and a popular "after-chop" is fruit salad. In Eastern Africa, Swahili people make a Saladi ya Matunda for dessert (See note at bottom of recipe). One interesting thing about the African fruit salad is the use of the avocado. A perfectly fine fruit salad can be made from just three or four of the ingredients listed below. A fruit salad makes a fine dessert course for an African-style dinner." Modified from, www.congocookbook.com.',NULL,'PT12M','PT12M',NULL,'1 fruit salad','["If using canned fruits: drain and save the liquid. Peel and remove seeds from the fresh fruit as necessary, cut fruit into bite-sized pieces.", "Combine all fruit in a glass bowl. Add the lemon juice, some of the liquid from the canned fruits or honey/sugar. Stir gently. There should only be enough liquid to coat the fruit; it does not have to be covered in liquid.", "Cover the fruit salad and allow it to stand at room temperature for a half hour before serving. The fruit salad may be refrigerated after it has stood up to an hour. It should be eaten the same day it is made.", "Garnish with freshly grated coconut or chopped roasted peanuts right before serving.", "NOTE: Eastern Africa''s Saladi Ya Matunda is made without the lemon juice, coconut or peanuts; it substitutes sugar/honey for the liquid from the canned fruits."]','["African", "Very Low Carbs", "Low Protein", "Low Cholesterol", "Healthy", "Free Of...", "Summer", "Sweet", "< 15 Mins", "Easy", "From Scratch"]',4.2,0.2,NULL,1.4,0.4,0.4,NULL,0.3,NULL,5.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
