INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('fc13b0fd-2591-46ea-af35-a1cfbf0ec5a9',456840,'Beans in Coconut Sauce (Maharagwe Ya Nasi)','African','This is a popular African dish posted by chef Keith Famie. Simple and satisfying! Cook time does not include the time for the beans to soak overnight. Note: If you want to make this recipe easier/faster, feel free to substitute canned beans and canned tomatoes!','PT1H30M','PT15M','PT1H45M',4,NULL,'["Drain the beans (after soaking overnight in water).", "Put the beans and water into a stockpot. Simmer over medium heat for 1 to 1 1/2 hours, or until the beans are tender. Drain and return the beans to the stockpot.", "Heat the olive oil in a saute pan over medium heat. Sweat the onions, tomatoes and garlic until tender. Add the onion mixture to the beans. Add the coconut milk and bring to a simmer over low heat. Cook for 5 minutes.", "Season with salt and pepper, to taste. Serve warm!"]','["Vegan", "< 4 Hours"]',317.9,12.1,16.1,34.9,9.9,3.9,NULL,28.7,11.3,5.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
