INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('98a12eb4-834c-4818-8407-7a7de0f3fa7a',21139,'Tanzanian Curried Chicken-Banana Soup','Chicken','Spicy, sweet, aromatic, and succulent all at once.This is a wonderful soup, reflective of the hot African sun of its origin.','PT50M','PT20M','PT1H10M',4,NULL,'["In a Dutch oven, brown the chicken pieces in the oil.", "Remove chicken, reserving, and add the onion and garlic to the pot.", "Saut\u00e9 until soft, then stir in the powdered chile, the curry, and the black pepper and fry for 2 more minutes.", "Add the tomatoes, stock, chicken pieces, and coconut, bring to a boil, then reduce heat and simmer for 30 minutes.", "When the chicken is done, remove, let cool, then strip away the meat and cut it into bite-sized chunks, discarding the skin and bones.", "Add it back into the pot with the banana chunks.", "Simmer 10 minutes.", "When ready to serve, ladle into bowls."]','["Poultry", "Fruit", "Meat", "African", "Weeknight", "Stove Top", "< 4 Hours"]',965.9,54.0,65.0,43.2,7.3,19.0,169.7,845.4,25.1,5.0,6,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
