INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('d6e9ff8e-5120-4790-9417-a1428c252fe0',55013,'East African Braised Chicken','Chicken','This is a wonderful dish I found in "Cooking Light" magazine. This dish if full of flavor and despite all the ingredients, it is very easy to make. It''s good served with rice and a flat bread. Braising in a this highly aromatic liquid yields an exceptionally flavorful and tender result.','PT1H','PT10M','PT1H10M',4,NULL,'["Preheat oven to 350\u00b0F.", "Sprinkle chicken with salt and black pepper.", "Heat oil in a Dutch oven over medium-high heat.", "Add chicken, cook 4 minutes on each side or until golden brown.", "Remove the chicken from pan.", "Add the onions to pan; reduce heat to medium-low, and cook for 10 minutes, stirring frequently.", "Add the ginger and next 5 ingredients (ginger through garlic), cook for 1 minute.", "Stir in chicken, broth and the remaining ingredients, and bring to a boil.", "Cover and bake at 350\u00b0F for 1 hour."]','["Poultry", "Meat", "African", "Weeknight", "< 4 Hours"]',856.4,59.1,56.6,26.3,3.2,15.1,243.8,523.5,15.7,5.0,9,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
