INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('25ab6120-9e90-4d91-9645-375737e88939',84311,'East African Tomato Chutney','Chutneys','This is a delicious, robust tomato condiment that can accompany grilled foods, curry, or as a mix-in for pasta or a baked potato topping. Try it in the summer with garden-fresh tomatoes - outstanding!','PT15M','PT20M','PT35M',4,NULL,'["Add about 2 tbsp. water to halved cherry or grape tomatoes in a sauce pan.", "Bring to a boil, then simmer until tomatoes are softened and slightly broken up, about 10 to 15 minutes.", "Remove from heat, and stir in onions, cilantro, parsley, jalapeno, lemon juice and salt.", "Let flavors meld for about an hour, then serve, preferably at room temperature."]','["Sauces", "Vegetable", "African", "Low Protein", "Vegan", "Low Cholesterol", "Healthy", "Summer", "Savory", "< 60 Mins", "Easy", "Inexpensive"]',20.8,0.9,0.2,4.6,1.3,2.6,NULL,296.6,NULL,5.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
