INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('17127bdc-1120-4ca3-b672-ae3fa3ba3c09',87002,'East African Pea Soup','African','This is a recipe I saw originally in the Sundays at Moosewood cookbook. I use some of the habanero peppers I grow to add heat to this soup, but the original recipe called for about 1/8 teaspoon cayenne. Jalapenos or other hot chiles would also be good substitutes for the habs, although they are by far my favorite hot pepper.','PT15M','PT30M','PT45M',6,NULL,'["Saut\u00e9 the onions gently in oil in a covered pot, stirring frequently, for 5 to 10 minutes, until the onions are just translucent.", "Add garlic and saute for 1 minute.", "Mix in the ginger, salt and all the spices and saut\u00e9 for 2 minutes, stirring often.", "Add the tomatoes and sweet potato.", "Stir well.", "Add 1 1/2 cups water and stir.", "Bring the soup to a boil.", "Reduce the heat and simmer, covered for 5 minutes.", "Add half of the peas and simmer, covered, for another 10 minutes, or until the peas and sweet potato are tender.", "Remove the soup from the heat and stir in the remaining 2 cups of water.", "Pur\u00e9e the soup in a blender or food processor in batches until smooth.", "Return soup to the pot, add the remaining peas and gently reheat."]','["Vegan", "< 60 Mins"]',133.8,5.4,2.9,23.1,5.5,8.8,NULL,492.3,0.4,4.0,4,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
