INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('4f3b5bf2-a3e4-41e0-9aaf-b1300223b23f',235859,'Ugandan Plantains With Chicken Stew','Stew','Make and share this Ugandan Plantains With Chicken Stew recipe from Food.com.','PT1H','PT20M','PT1H20M',6,NULL,'["Peel the plantains and place in a steamer or a saucepan with a rack in the bottom. Add water, leaving the bananas above the level of the water. Add salt and pepper. Bring contents to boiling point; reduce heat and steam bananas until soft.", "Lift bananas from the liquid and mash well. Place in top of double saucepan over simmering water until ready to serve with Chicken stew.", "To make Chicken stew:", "Fry Chicken in hot oil in a heavy saut\u00e9 pan until brown. Add onions, tomatoes, potatoes, salt, pepper and water. Cover tightly and simmer for about 1 hour, or until Chicken is tender.", "Pour Chicken stew over plantains."]','["Chicken", "Poultry", "Meat", "African", "< 4 Hours", "Easy"]',830.6,46.6,44.1,65.5,6.3,25.9,170.8,756.9,11.2,5.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
