INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('b58137b5-7c0f-433d-9813-a8f7eef8675a',235939,'Ugandan Groundnut Stew','Stew','In response to recipe requests - Ground nuts (like peanuts) are an important part of the diet. They are roasted, pounded to a pulp and then made into a sauce which may be used with meat or vegetables. Here is a recipe using peanut butter, which you might like to try.','PT1H30M','PT15M','PT1H45M',NULL,NULL,'["Remove seed from chillies and chop them finely.", "Mix them with the peanut butter, ginger, herbs, vegetables and tomatoes.", "Place meat in a saucepan with a tight fitting lid and add the vegetable mixture and some seasoning.", "Put on the lid and cook very gently for about one and a half hours or until the meat is tender.", "Don''t worry about the lack of liquid because the meat and vegetables will make enough."]','["Meat", "African", "< 4 Hours", "Easy"]',539.4,30.0,34.5,31.4,8.1,15.8,75.4,282.8,11.4,5.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
