INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('122ea4fc-a98d-4b56-ba13-4aab747b5f17',235945,'Ugandan Matoke','Stew','Matoke (or Matooke) refer to the plantain or plantain banana in Uganda, where plantains are a staple crop. In Uganda, plantain bananas are often wrapped in plantain leaves and steamed until tender.  This dish can be made with or without the meat.','PT1H','PT20M','PT1H20M',NULL,NULL,'["Peel the plantains, cut into cubes, sprinkle with lemon juice, and set aside.", "Heat oil in a large pan. Fry the Onion, tomatoes, green pepper, hot pepper, and garlic together. Add spices to taste. Add meat or broth. Continue frying and stirring until the meat is nearly done or until the broth is starting to boil.", "Reduce heat. Add plantains. Cover and simmer over low heat until plantains are tender and meat is done. Serve matoke (matooke, if you prefer) hot."]','["Vegetable", "Meat", "African", "Low Protein", "Low Cholesterol", "Healthy", "< 4 Hours", "Easy"]',468.7,5.8,1.5,121.5,9.9,57.2,NULL,19.5,0.6,4.0,6,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
