INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('6cbfec83-9c20-4028-96eb-0185c8f71937',305011,'Zanzibari Beans With Coconut and Cilantro','Vegetable','POSTED FOR ZWT 4. A vegetarian main dish from Zanzibar, which is part of Tanzania. I am uncertain about cooking and prep times!! The recipe was written down by Troth Well. It is served with vegetables and rice, sometimes with Jollof Rice. As usual I had to guess prep times and did not include the possible preparation of the black-eyed peas (or beans).','PT20M','PT15M','PT35M',4,NULL,'["Heat oil and sizzle the garlic and chilli powder for half a minute.", "Next, add the cumin, coriander, turmeric and cilantro. Cook another minute or so, stirring often.", "Add the coconut and fold it into the mixture. Add the cooked beans and potatoes.", "Season, and add the lemon or lime juice. Cook gently for about 10 minutes until everything is blended together.", "This is served with green vegetables and rice."]','["African", "< 60 Mins"]',293.1,5.8,21.6,22.8,7.3,2.0,NULL,193.6,13.3,4.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
