INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('650475a8-44cf-4bd3-a4c0-9e352fbe7d9b',309611,'Vegetable Curry (Kenya)','Curries','Make and share this Vegetable Curry (Kenya) recipe from Food.com.','PT45M','PT15M','PT1H',NULL,NULL,'["Preheat oven to 350\u00b0F.", "In a large, heavy skillet or pot, brown onions in moderately hot oil along with the cumin seeds and mustard seeds.", "Add the potato pieces and stir to coat each piece with spices.", "Add remaining spices and continue to stir for several minutes.", "Thin the tomato paste with 2/3 cup of water and stir into the pot.", "Add vegetables, one at a time, cooking for a minute or so between each addition, add chickpeas last.", "If your pot isn\u2019t oven proof transfer mixture to one that is and cover with a lid or seal with foil, and bake for about 45 minutes, checking after the first 20 minutes.", "The consistency of this curry should be thick, rather than watery, but add more liquid if needed to prevent burning. Stir occasionally to keep ingredients from sticking to the bottom of the pot.", "Serve over rice or with Indian bread."]','["Cauliflower", "Greens", "Onions", "Vegetable", "African", "Vegan", "< 60 Mins"]',348.6,11.6,5.1,68.2,13.7,10.0,NULL,589.2,0.7,5.0,3,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
