INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('4d1e59a4-e71a-467a-a947-67ad45ccbfd5',310245,'East African Roast Chicken','Whole Chicken','Make and share this East African Roast Chicken recipe from Food.com.','PT1H45M','PT24H','PT25H45M',6,NULL,'["Remove the giblets from the chicken, if necessary, rinse out the cavity and pat the skin dry.", "Put the butter and all the remaining ingredients in a bowl and mix together well to form a thick paste.", "Gently ease the skin of the chicken away from the flesh and rub generously with the herb and butter mixture. Rub more of the mixture over the skin, legs and wings of the chicken and into the neck cavity.", "Place the chicken in a roasting tin, cover loosely with foil and marinate overnight in the fridge.", "Preheat oven to 375F/190\u00b0C.", "Cover the chicken with clean foil and roast for 1 hour, then turn the chicken over and baste with the pan juices.", "Cover again with foil and cook for 30 minutes.", "Remove the foil and place the chicken breast-side up. Rub with a little extra butter and roast for a further 10-15 minutes until the meat juices run clear and the skin is golden brown.", "Serve with a rice dish or a salad."]','["Chicken", "Poultry", "Meat", "African", "Very Low Carbs", "High Protein", "High In..."]',497.4,34.0,37.0,2.9,0.3,0.8,152.8,170.0,13.2,4.0,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
