INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('36d4a6f1-c0d3-464a-a374-836ffaac2b62',400284,'Zanzibari Chutney (Part of Zanzibari Pulao/Pilaf)','Chutneys','Growing up in Dubai there was a tiny restaurant my father would occasionally take us to. They were famous for & only served Zanzibari Pulao along with a cold glass of the drink Tang. After moving out of Dubai the only option I had to still eat the pulao was to come up with something at home. After many trials my mom came up with this chutney recipe. This chutney is part of the Zanzibari Pulao that I have posted. Pakistani Bhagaare Chawal (Stir Fried Rice) or Zanzabari Pulao recipe #282570
