INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('9b5d366a-667e-442d-bfcd-5dfaddd30cd0',455495,'Pina Colada from the Mangapwani Beach Club in Zanzibar','Beverages','The original recipe is from the Mangapwani Beach Club.  Located on the northwest coast of Zanzibar, South Africa, this beach paradise has a checkered past.  Nearby are the Slave Caves, where slaves were hidden after laws changed abolishing slavery. The Mangapwani Beach Club overlooks the beautiful waters of the Indian Ocean. The original recipe is from "Around the World in 80 Bars".  I increased the rum from 2 oz to 3 oz per serving. Serve in a hurricane glass with long straws and garnish with a wedge of fresh pineapple.  Enjoy!',NULL,'PT10M','PT10M',1,NULL,'["Place all the ingredients in a blender with some ice and process on high speed until mixed well. (Start with a small amount of ice and adjust to your desired thickness).", "Serve in a large hurricane glass with long straws and a wedge of fresh pineapple to garnish."]','["Low Protein", "Low Cholesterol", "Healthy", "< 15 Mins", "Small Appliance", "Easy"]',566.1,3.2,16.7,54.2,0.7,49.3,29.0,75.5,13.3,4.0,1,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
