INSERT INTO recipes (id,source_id,name,category,description,cook_time,prep_time,total_time,servings,yield,instructions,keywords,calories,protein_g,fat_g,carbs_g,fiber_g,sugar_g,cholesterol_mg,sodium_mg,saturated_fat_g,rating,review_count,created_at,updated_at) VALUES ('6e8205e7-40de-468b-aae3-977db6385025',455783,'Ugandan Vegetable Casserole','Spinach','The variations possible with this colorful vegetable casserole are endless. Either make it with the vegetables listed here or substitute your own favorites.','PT30M','PT15M','PT45M',NULL,NULL,'["In a large frying pan, heat oil over medium-high heat for 4 to 5 minutes.", "Add onions to pan and stir-fry for 2 to 3 minutes. Continue to add vegetables to pan in order listed, stir-frying each 2 to 3 minutes before adding the next.", "Stir in salt and black pepper. Cover pan, reduce heat to low, and simmer 10 to 15 minutes or until vegetables are tender.", "Serve immediately."]','["Greens", "Vegetable", "African", "Low Protein", "Low Cholesterol", "< 60 Mins"]',149.4,6.0,7.8,18.3,8.9,7.6,NULL,390.2,1.1,4.5,2,'2026-08-25 08:21:58','2026-08-25 08:21:58') ON CONFLICT (source_id) DO NOTHING;
